/* TESTS GENERATED BY CLAUDE - to be checked more in future */


/**
 * @file test_soh.c
 * @brief Host-side unit tests for common/soh.c (pack/unpack).
 *
 * Built and run on a development machine, not on target hardware:
 *   cmake -S tests/host -B build/host-tests
 *   cmake --build build/host-tests
 *   ctest --test-dir build/host-tests --output-on-failure
 *
 * Each test uses assert(). A failed assert aborts the program, which
 * CTest reports as a failure along with the failing line.
 */

/* Keep assert() active even in Release builds. Must come before <assert.h>. */
#undef NDEBUG
#include <assert.h>
#include <stdio.h>
#include <string.h>

#include "common/soh.h"

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/* Compare structs field by field (memcmp is unsafe: padding bytes). */
static void assert_core_equal(const soh_core_t *a, const soh_core_t *b)
{
    assert(a->uptime_s    == b->uptime_s);
    assert(a->vdd_mv      == b->vdd_mv);
    assert(a->temp_c      == b->temp_c);
    assert(a->version     == b->version);
    assert(a->reset_cause == b->reset_cause);
}

static void assert_can_equal(const soh_can_t *a, const soh_can_t *b)
{
    assert(a->tec              == b->tec);
    assert(a->rec              == b->rec);
    assert(a->can_flags        == b->can_flags);
    assert(a->bus_off_count    == b->bus_off_count);
    assert(a->error_irq_count  == b->error_irq_count);
    assert(a->rx_overrun_count == b->rx_overrun_count);
}

/* Pack then unpack a Core struct; result must match the input. */
static void core_round_trip(soh_core_t in)
{
    uint8_t bytes[SOH_FRAME_LEN];
    soh_core_t out;

    in.version = SOH_SCHEMA_VERSION; /* pack always writes this */
    soh_pack_core(&in, bytes);
    assert(soh_unpack_core(bytes, sizeof bytes, &out));
    assert_core_equal(&in, &out);
}

static void can_round_trip(soh_can_t in)
{
    uint8_t bytes[SOH_FRAME_LEN];
    soh_can_t out;

    soh_pack_can(&in, bytes);
    assert(soh_unpack_can(bytes, sizeof bytes, &out));
    assert_can_equal(&in, &out);
}

/* The documented example: 3600 s, 3312 mV, 24 C, version 1, WATCHDOG. */
static const uint8_t CORE_EXAMPLE_BYTES[SOH_FRAME_LEN] = {
    0x00, 0x00, 0x0E, 0x10, 0x0C, 0xF0, 0x18, 0x13
};

static soh_core_t core_example(void)
{
    soh_core_t c = {
        .uptime_s    = 3600,
        .vdd_mv      = 3312,
        .temp_c      = 24,
        .version     = SOH_SCHEMA_VERSION,
        .reset_cause = SOH_RESET_WATCHDOG,
    };
    return c;
}

/* ------------------------------------------------------------------ */
/* SOH Core tests                                                      */
/* ------------------------------------------------------------------ */

static void test_core_known_vector_pack(void)
{
    soh_core_t in = core_example();
    uint8_t bytes[SOH_FRAME_LEN];

    soh_pack_core(&in, bytes);
    assert(memcmp(bytes, CORE_EXAMPLE_BYTES, SOH_FRAME_LEN) == 0);
}

static void test_core_known_vector_unpack(void)
{
    soh_core_t expected = core_example();
    soh_core_t out;

    assert(soh_unpack_core(CORE_EXAMPLE_BYTES, SOH_FRAME_LEN, &out));
    assert_core_equal(&out, &expected);
}

static void test_core_pack_ignores_struct_version(void)
{
    soh_core_t in = core_example();
    uint8_t bytes[SOH_FRAME_LEN];

    in.version = 9; /* wrong on purpose */
    soh_pack_core(&in, bytes);
    assert((bytes[7] >> 4) == SOH_SCHEMA_VERSION);
}

static void test_core_round_trips(void)
{
    core_round_trip((soh_core_t){ .uptime_s = 1,      .vdd_mv = 3300, .temp_c = 20,  .reset_cause = SOH_RESET_POWER_ON });
    core_round_trip((soh_core_t){ .uptime_s = 86400,  .vdd_mv = 5000, .temp_c = -10, .reset_cause = SOH_RESET_BROWNOUT });
    core_round_trip((soh_core_t){ .uptime_s = 123456, .vdd_mv = 1800, .temp_c = 85,  .reset_cause = SOH_RESET_LOCKUP_OTHER });

    /* every valid reset cause survives */
    for (int c = 0; c < SOH_RESET_COUNT; c++) {
        core_round_trip((soh_core_t){ .uptime_s = 10, .vdd_mv = 3300, .temp_c = 25,
                                      .reset_cause = (soh_reset_cause_t)c });
    }
}

static void test_core_extremes(void)
{
    core_round_trip((soh_core_t){ .uptime_s = 0,          .vdd_mv = 0,      .temp_c = 0 });
    core_round_trip((soh_core_t){ .uptime_s = 0xFFFFFFFF, .vdd_mv = 0xFFFE, .temp_c = 127 });
    core_round_trip((soh_core_t){ .uptime_s = 0xFFFFFFFF, .vdd_mv = 1,      .temp_c = -127 });
}

static void test_core_negative_temp_byte(void)
{
    soh_core_t in = core_example();
    uint8_t bytes[SOH_FRAME_LEN];

    in.temp_c = -5;
    soh_pack_core(&in, bytes);
    assert(bytes[6] == 0xFB); /* two's complement */
}

static void test_core_sentinels(void)
{
    soh_core_t in = core_example();
    uint8_t bytes[SOH_FRAME_LEN];
    soh_core_t out;

    in.vdd_mv = SOH_VDD_INVALID;
    in.temp_c = SOH_TEMP_INVALID;
    soh_pack_core(&in, bytes);

    /* sentinels are valid messages, not errors */
    assert(soh_unpack_core(bytes, sizeof bytes, &out));
    assert(out.vdd_mv == SOH_VDD_INVALID);
    assert(out.temp_c == SOH_TEMP_INVALID);
}

static void test_core_rejects_bad_length(void)
{
    uint8_t bytes[SOH_FRAME_LEN + 1] = { 0 };
    soh_core_t out;

    memcpy(bytes, CORE_EXAMPLE_BYTES, SOH_FRAME_LEN);
    assert(!soh_unpack_core(bytes, 0, &out));
    assert(!soh_unpack_core(bytes, SOH_FRAME_LEN - 1, &out));
    assert(!soh_unpack_core(bytes, SOH_FRAME_LEN + 1, &out));
}

static void test_core_rejects_bad_version(void)
{
    uint8_t bytes[SOH_FRAME_LEN];
    soh_core_t out;

    memcpy(bytes, CORE_EXAMPLE_BYTES, SOH_FRAME_LEN);
    bytes[7] = 0x03; /* version 0, WATCHDOG */
    assert(!soh_unpack_core(bytes, sizeof bytes, &out));

    bytes[7] = 0x23; /* version 2, WATCHDOG */
    assert(!soh_unpack_core(bytes, sizeof bytes, &out));
}

static void test_core_rejects_bad_reset_cause(void)
{
    uint8_t bytes[SOH_FRAME_LEN];
    soh_core_t out;

    memcpy(bytes, CORE_EXAMPLE_BYTES, SOH_FRAME_LEN);
    for (unsigned c = SOH_RESET_COUNT; c <= 0x0F; c++) {
        bytes[7] = (uint8_t)((SOH_SCHEMA_VERSION << 4) | c);
        assert(!soh_unpack_core(bytes, sizeof bytes, &out));
    }
}

static void test_core_rejects_null(void)
{
    soh_core_t out;

    assert(!soh_unpack_core(NULL, SOH_FRAME_LEN, &out));
    assert(!soh_unpack_core(CORE_EXAMPLE_BYTES, SOH_FRAME_LEN, NULL));
}

static void test_core_reject_leaves_out_untouched(void)
{
    uint8_t bytes[SOH_FRAME_LEN];
    soh_core_t out = core_example();
    soh_core_t before = out;

    memcpy(bytes, CORE_EXAMPLE_BYTES, SOH_FRAME_LEN);
    bytes[0] = 0xAA;  /* would change uptime if written */
    bytes[7] = 0x1F;  /* invalid reset cause -> reject */
    assert(!soh_unpack_core(bytes, sizeof bytes, &out));
    assert_core_equal(&out, &before);
}

/* ------------------------------------------------------------------ */
/* SOH CAN Stats tests                                                 */
/* ------------------------------------------------------------------ */

static void test_can_known_vector(void)
{
    soh_can_t in = {
        .tec = 1, .rec = 2,
        .can_flags = SOH_CANF_ERR_WARNING | SOH_CANF_ERR_PASSIVE,
        .bus_off_count = 4,
        .error_irq_count = 0x1234,
        .rx_overrun_count = 0xABCD,
    };
    const uint8_t expected[SOH_FRAME_LEN] = {
        0x01, 0x02, 0x03, 0x04, 0x12, 0x34, 0xAB, 0xCD
    };
    uint8_t bytes[SOH_FRAME_LEN];
    soh_can_t out;

    soh_pack_can(&in, bytes);
    assert(memcmp(bytes, expected, SOH_FRAME_LEN) == 0);

    assert(soh_unpack_can(expected, SOH_FRAME_LEN, &out));
    assert_can_equal(&out, &in);
}

static void test_can_round_trips_and_extremes(void)
{
    can_round_trip((soh_can_t){ 0 });
    can_round_trip((soh_can_t){ .tec = 96, .rec = 10, .can_flags = SOH_CANF_ERR_WARNING });
    can_round_trip((soh_can_t){ .tec = 255, .rec = 255, .can_flags = 0xFF,
                                .bus_off_count = 255,
                                .error_irq_count = 0xFFFF,
                                .rx_overrun_count = 0xFFFF });
}

static void test_can_rejects_bad_length_and_null(void)
{
    uint8_t bytes[SOH_FRAME_LEN + 1] = { 0 };
    soh_can_t out;

    assert(!soh_unpack_can(bytes, 0, &out));
    assert(!soh_unpack_can(bytes, SOH_FRAME_LEN - 1, &out));
    assert(!soh_unpack_can(bytes, SOH_FRAME_LEN + 1, &out));
    assert(!soh_unpack_can(NULL, SOH_FRAME_LEN, &out));
    assert(!soh_unpack_can(bytes, SOH_FRAME_LEN, NULL));
}

/* ------------------------------------------------------------------ */
/* Runner                                                              */
/* ------------------------------------------------------------------ */

#define RUN(test) do { test(); printf("PASS  %s\n", #test); passed++; } while (0)

int main(void)
{
    int passed = 0;

    RUN(test_core_known_vector_pack);
    RUN(test_core_known_vector_unpack);
    RUN(test_core_pack_ignores_struct_version);
    RUN(test_core_round_trips);
    RUN(test_core_extremes);
    RUN(test_core_negative_temp_byte);
    RUN(test_core_sentinels);
    RUN(test_core_rejects_bad_length);
    RUN(test_core_rejects_bad_version);
    RUN(test_core_rejects_bad_reset_cause);
    RUN(test_core_rejects_null);
    RUN(test_core_reject_leaves_out_untouched);

    RUN(test_can_known_vector);
    RUN(test_can_round_trips_and_extremes);
    RUN(test_can_rejects_bad_length_and_null);

    printf("\nAll %d SOH tests passed.\n", passed);
    return 0;
}